import{f as r,D as i,o as d,c as o,k as n,a as t,G as s,aq as l}from"./chunks/framework.CAfuRaXs.js";const p=JSON.parse('{"title":"Uhrzeitformat in Texten der Anwendung","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/adr-time-format.md","filePath":"technik/adr/adr-time-format.md"}'),u={name:"technik/adr/adr-time-format.md"};function h(c,e,m,g,f,z){const a=i("adr-status");return d(),o("div",null,[e[0]||(e[0]=n("h1",{id:"uhrzeitformat-in-texten-der-anwendung",tabindex:"-1"},[t("Uhrzeitformat in Texten der Anwendung "),n("a",{class:"header-anchor",href:"#uhrzeitformat-in-texten-der-anwendung","aria-label":'Permalink to "Uhrzeitformat in Texten der Anwendung"'},"​")],-1)),e[1]||(e[1]=n("h2",{id:"status",tabindex:"-1"},[t("Status "),n("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),s(a,{status:"accepted"}),e[2]||(e[2]=l('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>An verschiedenen Stellen innerhalb der Anwendung werden Uhrzeiten angezeigt. Je nach Kontext und anzuzeigender Uhrzeit haben die Minuten und Sekunden keine Relevanz, sodass diese weggelassen werden können.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><p>Uhrzeiten werden prinzipiell im Format <code>hh:mm</code> angezeigt. Dabei wird für die Stunden auch eine führende Null genutzt (z.B. <code>09:22 Uhr</code>).</p><p>Es gibt folgende Ausnahmen:</p><ul><li>volle Stunden werden ohne Minuten und Sekunden angezeigt (<code>18:00 Uhr</code> wird zu <code>18 Uhr</code>). Die führende Null für die Stunden fällt dabei weg (<code>09:00 Uhr</code> wird zu <code>9 Uhr</code>).</li><li>für die Fehlermeldungen der Uhrzeit-Eingabefelder gilt diese Ausnahme nicht. Hier werden auch die Minuten bei einer vollen Stunde angezeigt, da das Eingabefeld das Format <code>hh:mm</code> erwartet</li><li>die WLS-Clock und die letzte Absendezeit beim Wahlvorstand wird mit Sekunden angezeigt</li><li>in fremdgesteuerten Drucktemplates (Ergebnismeldung) wird das Uhrzeitformat unverändert übernommen</li></ul><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><ul><li>Vereinheitlichung des Uhrzeitformats führt zu einem besseren Verständnis der Zeitangaben</li><li>Es werden nur die relevanten Teile der Uhrzeit angezeigt</li></ul>',8))])}const k=r(u,[["render",h]]);export{p as __pageData,k as default};
